query CoverageLens($window: DateRange) {
  sources {
    ...DataThroughFields
  }
  coverage(source: SEAP, window: $window) {
    window {
      from
      to
    }
    counties {
      county
      status
      withRecords
      publicEntities
      otherAuthorities
    }
    unplacedAuthorities {
      authorities
      total {
        ...TotalFields
      }
    }
  }
}

fragment DataThroughFields on Source {
  id
  name
  harvested
  dataThrough {
    kind
    date
  }
}

fragment TotalFields on Total {
  awarded
  records
  suspectLeftOut
  noValue
  frameworkCeilings
  estimated
}

query CoveragePage($window: DateRange) {
  sources {
