query EntityOverview($key: ID!, $role: Role!, $filter: RecordFilter, $signalOrder: SignalOrder, $signalOffset: Int) {
  entity(key: $key) {
    ...EntityHeaderFields
    onrc {
      ...OnrcRegistrationFields
    }
    people {
      ...OrganisationPeopleFields
    }
    publicEnterprise {
      ...PublicEnterpriseFields
    }
    leadership {
      ...LeadershipFields
    }
    financials {
      ...FinancialStatementsFields
    }
    donations {
      ...FirmDonationsFields
    }
    seap {
      role(role: $role) {
        role
        total(filter: $filter) {
          ...TotalFields
        }
        counterparties(filter: $filter, limit: 10) {
          count
          topShare
          rows {
            entity {
              ...EntityRef
            }
            naturalPerson
            total {
              ...TotalFields
            }
          }
        }
        directPurchaseShare(filter: $filter)
        procedures(filter: $filter) {
          value
          total {
            ...TotalFields
          }
        }
        consortia(filter: $filter, limit: 10) {
          members {
            ...PartyFields
          }
          total {
            ...TotalFields
          }
        }
        frameworks(filter: $filter) {
          count
          ceilings
          subsequentReported
        }
        largestRecords(filter: $filter, limit: 10) {
          ...RecordRowFields
        }
        signals(filter: $filter, order: $signalOrder, limit: 20, offset: $signalOffset) {
          count
          rows {
            ...SignalFields
            records(limit: 1) {
              code
              provenance {
                url
              }
            }
          }
        }
      }
    }
  }
}

