query ZoomedCounty($filter: RecordFilter!, $county: CountyCode!) {
  uats(county: $county) {
    siruta
    name
    county {
      code
      name
    }
  }
  seap {
    search(filter: $filter) {
      total {
        ...TotalFields
      }
      uatMap(county: $county) {
        uats {
          area
          name
          entities
          total {
            ...TotalFields
          }
        }
        unknownUat {
          ...TotalFields
        }
      }
    }
  }
}

fragment TotalFields on Total {
  awarded
  records
  suspectLeftOut
  noValue
  frameworkCeilings
  estimated
}
